describe('Table Summary Row - Numeric Column', () => {
  beforeEach(() => {
    cy.visit('/table');
    cy.get('[data-testid="numeric-table"]').should('be.visible');
  });

  it('should display summary row at the bottom of numeric column with correct total', () => {
    // Verify table is loaded
    cy.get('[data-testid="numeric-table"] tbody tr').should('have.length.greaterThan', 0);

    // Get all numeric values from the column
    const numericValues = [];
    cy.get('[data-testid="numeric-column"] [data-testid="numeric-cell"]').each(($cell) => {
      const value = parseFloat($cell.text().replace(/[^0-9.-]/g, ''));
      if (!isNaN(value)) {
        numericValues.push(value);
      }
    });

    // Verify summary row exists
    cy.get('[data-testid="summary-row"]').should('be.visible');

    // Verify summary row is at the bottom
    cy.get('[data-testid="numeric-table"] tbody tr').last().should('have.attr', 'data-testid', 'summary-row');

    // Verify summary label
    cy.get('[data-testid="summary-row"] [data-testid="summary-label"]')
      .should('contain', 'Total');

    // Verify summary value matches expected total
    cy.get('[data-testid="summary-row"] [data-testid="summary-value"]').then(($summaryCell) => {
      const summaryValue = parseFloat($summaryCell.text().replace(/[^0-9.-]/g, ''));
      const expectedTotal = numericValues.reduce((a, b) => a + b, 0);
      expect(summaryValue).to.equal(expectedTotal);
    });

    // Verify summary row styling
    cy.get('[data-testid="summary-row"]').should('have.class', 'summary-row-style');
  });

  it('should handle empty table and display zero in summary row', () => {
    // Clear table data
    cy.get('[data-testid="clear-table-btn"]').click();

    // Verify table is empty
    cy.get('[data-testid="numeric-table"] tbody tr').should('have.length', 1);

    // Verify summary row still exists
    cy.get('[data-testid="summary-row"]').should('be.visible');

    // Verify summary value is zero
    cy.get('[data-testid="summary-row"] [data-testid="summary-value"]')
      .should('contain', '0');
  });

  it('should update summary row when numeric values change', () => {
    // Get initial summary value
    cy.get('[data-testid="summary-row"] [data-testid="summary-value"]').then(($initial) => {
      const initialValue = parseFloat($initial.text().replace(/[^0-9.-]/g, ''));

      // Edit a numeric cell
      cy.get('[data-testid="numeric-cell"]').first().click();
      cy.get('[data-testid="numeric-cell-input"]').clear().type('999');
      cy.get('[data-testid="numeric-cell-input"]').blur();

      // Verify summary row updated
      cy.get('[data-testid="summary-row"] [data-testid="summary-value"]').then(($updated) => {
        const updatedValue = parseFloat($updated.text().replace(/[^0-9.-]/g, ''));
        expect(updatedValue).to.not.equal(initialValue);
        expect(updatedValue).to.be.greaterThan(initialValue);
      });
    });
  });

  it('should handle negative numbers in summary calculation', () => {
    // Add row with negative value
    cy.get('[data-testid="add-row-btn"]').click();
    cy.get('[data-testid="numeric-cell-input"]').last().type('-50');
    cy.get('[data-testid="numeric-cell-input"]').last().blur();

    // Verify summary row includes negative value
    cy.get('[data-testid="summary-row"] [data-testid="summary-value"]').then(($summary) => {
      const summaryValue = parseFloat($summary.text().replace(/[^0-9.-]/g, ''));
      expect(summaryValue).to.be.a('number');
      // Verify calculation includes the negative number
      cy.get('[data-testid="numeric-column"] [data-testid="numeric-cell"]').then(($cells) => {
        let expectedTotal = 0;
        $cells.each((index, cell) => {
          const value = parseFloat(cell.textContent.replace(/[^0-9.-]/g, ''));
          if (!isNaN(value)) {
            expectedTotal += value;
          }
        });
        expect(summaryValue).to.equal(expectedTotal);
      });
    });
  });

  it('should display summary row with decimal precision', () => {
    // Verify summary value respects decimal places
    cy.get('[data-testid="summary-row"] [data-testid="summary-value"]')
      .should('match', /\d+\.\d{2}/);

    // Verify no rounding errors in display
    cy.get('[data-testid="summary-row"] [data-testid="summary-value"]').then(($summary) => {
      const summaryText = $summary.text();
      const decimalPart = summaryText.split('.')[1];
      expect(decimalPart).to.have.length(2);
    });
  });

  it('should maintain summary row position when scrolling table', () => {
    // Add multiple rows to enable scrolling
    for (let i = 0; i < 20; i++) {
      cy.get('[data-testid="add-row-btn"]').click();
    }

    // Scroll table
    cy.get('[data-testid="numeric-table"]').scrollTo('bottom');

    // Verify summary row is still visible and at bottom
    cy.get('[data-testid="summary-row"]').should('be.visible');
    cy.get('[data-testid="numeric-table"] tbody tr').last().should('have.attr', 'data-testid', 'summary-row');
  });
});
